-- Insert ratings for all 6000 movies
INSERT OR IGNORE INTO "ratings" ("id", "movie_id", "rating", "votes") VALUES
(1, 1, 9.3, 2800000),
(2, 2, 9.2, 1900000),
(3, 3, 9.0, 2500000),
(4, 4, 9.0, 1300000),
(5, 5, 9.0, 800000);

-- Generate ratings for all 6000 movies
INSERT OR IGNORE INTO "ratings" ("id", "movie_id", "rating", "votes")
SELECT 
    m.id,
    m.id,
    CAST((RANDOM() % 40 + 60) AS REAL) / 10,
    CAST((RANDOM() % 1000000 + 100000) AS INTEGER)
FROM "movies" m
WHERE m.id > 5 AND m.id <= 6000;

-- Generate 10000+ star relationships
-- Each movie gets at least 2 stars (6000 * 2 = 12000)
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id <= 2
AND m.id <= 6000;

-- Add more stars for first 2000 movies
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 3 AND 12
AND m.id <= 2000;

-- Add more stars for next 2000 movies
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 13 AND 22
AND m.id BETWEEN 2001 AND 4000;

-- Add more stars for remaining movies
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 23 AND 32
AND m.id BETWEEN 4001 AND 6000;

-- Add extra stars to ensure over 10000 relationships
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 33 AND 50
AND m.id <= 1000;

-- Add more for additional coverage
INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 51 AND 70
AND m.id <= 500;

INSERT OR IGNORE INTO "stars" ("movie_id", "person_id")
SELECT m.id, p.id
FROM "movies" m
CROSS JOIN "people" p
WHERE p.id BETWEEN 71 AND 90
AND m.id <= 200;